DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.save_location_to_engine(uuid,uuid,timestamptz,jsonb,jsonb,jsonb)'::regprocedure) INTO d;d:=replace(d,'FOR item IN SELECT * FROM jsonb_array_elements(p_lines) LOOP','IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_lines) x GROUP BY x->>''line_kind'',lower(trim(x->>''label'')) HAVING count(*)>1) THEN RAISE EXCEPTION ''Combine duplicate role or asset lines'';END IF; IF accepted AND p_values->>''kind''<>''initial'' AND NOT EXISTS(SELECT 1 FROM location_task_orders WHERE location_id=p_location AND status=''accepted'' AND kind=''initial'' AND id<>result_id) THEN RAISE EXCEPTION ''Save an initial TO before changes'';END IF; FOR item IN SELECT * FROM jsonb_array_elements(p_lines) LOOP');d:=replace(d,'t.effective_date<=(p_values->>''effective_date'')::date','(t.effective_date+COALESCE(t.effective_time,''00:00''::time))<=((p_values->>''effective_date'')::date+COALESCE((p_values->>''effective_time'')::time,''00:00''::time))');d:=replace(d,'IF current_count+delta<0 THEN','IF (p_values->>''kind'' IN(''initial'',''increase'') AND delta<0) OR (p_values->>''kind'' IN(''decrease'',''demobilization'') AND delta>0) THEN RAISE EXCEPTION ''Quantity direction must match TO kind'';END IF; IF current_count+delta<0 THEN');d:=replace(d,'IF p_id IS NULL THEN INSERT','DELETE FROM location_to_sheets WHERE task_order_id=result_id; IF p_id IS NULL THEN INSERT');EXECUTE d;
SELECT pg_get_functiondef('public.location_to_billing_sources(uuid)'::regprocedure) INTO d;d:=replace(d,'jsonb_agg(to_jsonb(t))','jsonb_agg(to_jsonb(t)||jsonb_build_object(''terms_only'',NOT EXISTS(SELECT 1 FROM location_task_order_lines ln WHERE ln.task_order_id=t.id)))');EXECUTE d;END $$;
REVOKE INSERT,UPDATE,DELETE ON public.location_to_terms,public.location_to_sheets FROM authenticated;GRANT SELECT ON public.location_to_terms,public.location_to_sheets TO authenticated;